import {ownRecord} from './state-validation.mjs';
// Original fictional records and adult facilitation choices, not empirical predictions.
export const comparisonRecords=[
 {id:'a',shape:'Plano',paper:'Fino',gap:'Dos marcas',load:3},
 {id:'b',shape:'Plegado',paper:'Fino',gap:'Dos marcas',load:6},
 {id:'c',shape:'Plegado',paper:'Grueso',gap:'Tres marcas',load:5},
 {id:'d',shape:'Plegado',paper:'Grueso',gap:'Dos marcas',load:8}
];
export const newExploration=stage=>stage==='7y'?{open:true,page:0,left:'a',right:'c',revealed:false,hint:false}:{open:true,page:0,start:'wave',ending:'rest',original:'rest',hint:false};
export function compareRecords(s){
 const left=comparisonRecords.find(r=>r.id===s.left),right=comparisonRecords.find(r=>r.id===s.right);
 const changed=['shape','paper','gap'].filter(k=>left[k]!==right[k]),target=s.page===0?'shape':'paper';
 return {left,right,changed,focused:changed.length===1&&changed[0]===target,difference:right.load-left.load};
}
export function validateExploration(raw,stage){
 const science=stage==='7y',keys=science?['open','page','left','right','revealed','hint']:['open','page','start','ending','original','hint'];
 ownRecord(raw,keys);
 if(!['7y','2y'].includes(stage)||!raw||typeof raw!=='object'||Array.isArray(raw)||Object.keys(raw).some(k=>!keys.includes(k))||typeof raw.open!=='boolean'||typeof raw.hint!=='boolean'||!Number.isInteger(raw.page)||raw.page<0||raw.page>2)throw Error('Invalid exploration');
 if(science){if(typeof raw.revealed!=='boolean'||![raw.left,raw.right].every(x=>comparisonRecords.some(r=>r.id===x))||raw.page===2&&(!raw.revealed||!compareRecords(raw).focused))throw Error('Invalid comparison');}
 else if(!['wave','peek'].includes(raw.start)||![raw.ending,raw.original].every(x=>['rest','walk','stop'].includes(x)))throw Error('Invalid adult story');
 return {...raw};
}
const names={shape:'forma',paper:'grosor del papel',gap:'separación de los apoyos'};
const drawing=r=>`<svg viewBox="0 0 240 100" class="exploration-art" aria-hidden="true"><rect x="20" y="48" width="34" height="40" rx="3" fill="#a4b39a"/><rect x="${r.gap==='Dos marcas'?170:195}" y="48" width="25" height="40" rx="3" fill="#a4b39a"/><path d="${r.shape==='Plano'?'M30 43H210':'M30 43L60 30L90 43L120 30L150 43L180 30L210 43'}" fill="none" stroke="#215747" stroke-width="${r.paper==='Fino'?3:7}"/></svg>`;
const storyArt=(gesture,gestures=false)=>`<svg viewBox="0 0 240 100" class="exploration-art" aria-hidden="true"><circle cx="110" cy="25" r="15" fill="#e4bc69"/><path d="M110 42V70 M110 50L82 ${gesture==='rest'?65:gesture==='stop'?50:25} M110 50L145 ${gesture==='rest'?65:gesture==='stop'?50:25} M110 70L${gesture==='walk'?80:100} 90 M110 70L${gesture==='walk'?145:120} 90" stroke="#215747" stroke-width="6" fill="none" stroke-linecap="round"/>${gestures?'<path d="M175 75V45q0-8 6-8t6 8v13V32q0-7 6-7t6 7v27q18-5 18 8v15" fill="none" stroke="#8d3e15" stroke-width="4"/>':''}</svg>`;
const beginnings={wave:'Saluda despacio',peek:'Aparece y desaparece a un lado'};
const endings={rest:'Descansar',walk:'Dar un paseo imaginario',stop:'Parar la historia'};
export function storyVersion(start,ending,gestures=false){
 const first=gestures?(start==='wave'?'Saluda con tu mano.':'Haz aparecer tu mano a un lado, sin tapar la cara del pequeño.'):(start==='wave'?'Saluda con el muñeco.':'Haz aparecer el muñeco a un lado.');
 const last=ending==='stop'?'Deja de actuar y espera. Puedes terminar aquí.':ending==='rest'?(gestures?'Junta tus manos como si descansaran.':'Apoya el muñeco en un lugar seguro como si descansara.'):(gestures?'Haz caminar dos dedos sobre tu propia palma.':'Mueve el muñeco unos pasos sobre una superficie estable.');
 return [first,last];
}
export function renderExploration(root,st,stage,{examples,finish}){
 const s=st.exploration,science=stage==='7y',comparison=science?compareRecords(s):null;
 const redraw=selector=>{renderExploration(root,st,stage,{examples,finish});root.querySelector(selector)?.focus();};
 const button=(id,label)=>`<button type="button" class="action secondary" id="${id}">${label}</button>`;
 const card=r=>`<article class="exploration-card"><h5>Registro ${r.id.toUpperCase()}</h5>${drawing(r)}<dl><dt>Forma</dt><dd>${r.shape}</dd><dt>Papel</dt><dd>${r.paper}</dd><dt>Apoyos</dt><dd>${r.gap}</dd></dl>${s.revealed?`<p><strong>${r.load} fichas</strong> en este registro inventado</p><div class="record-bar record-bar-${r.load}" aria-hidden="true"></div>`:'<p>Resultado oculto hasta comparar.</p>'}</article>`;
 const hint=science?(s.page===0?'Para mirar la forma, busca dos registros con papel fino y apoyos a dos marcas. Después comprueba si sus formas son distintas.':'Ahora importa el grosor: busca dos registros plegados con apoyos a dos marcas y distinto papel.'):'Muestra solo un gesto, espera y sigue su iniciativa. Si pierde interés, reduce la historia o para; no hace falta imitar.';
 let content='';
 if(science){const c=comparison;content=`<p class="notice">Registros y cifras inventados. No predicen cuánto soporta un puente real. No se propone construirlo ni cargarlo con objetos.</p><p>${s.page===0?'Pregunta inicial: ¿qué cambia entre una forma plana y una plegada? Elige dos registros para comparar.':s.page===1?'La pregunta cambia: ahora queremos comparar el grosor del papel. Conservamos los registros elegidos. ¿Sirven para esta nueva pregunta?':'Elegiste qué comparar, observaste los datos y revisaste el diseño al cambiar la pregunta.'}</p>${s.page<2?`<div class="exploration-selectors">${['left','right'].map((side,i)=>`<label>Registro ${i+1}<select data-record="${side}">${comparisonRecords.map(r=>`<option value="${r.id}" ${s[side]===r.id?'selected':''}>${r.id.toUpperCase()} · ${r.shape}, ${r.paper.toLowerCase()}, ${r.gap.toLowerCase()}</option>`).join('')}</select></label>`).join('')}</div>`:''}<div class="exploration-pair">${card(c.left)}${card(c.right)}</div>${s.page<2?`<div class="controls">${button('exploration-observe','Observar y comparar')}${button('exploration-hint','Una pista concreta')}</div>`:''}<div id="exploration-feedback" role="status" tabindex="-1">${s.revealed?`<p>${c.changed.length?'Cambian: '+c.changed.map(k=>names[k]).join(', ')+'.':'Los dos registros tienen las mismas condiciones.'} ${c.focused?'Esta pareja permite comparar la condición que buscamos dentro de este caso ficticio.':'Esta pareja no aísla la condición de la pregunta. Cambia un registro y observa de nuevo.'}</p><p>En estos registros: ${c.left.load} y ${c.right.load} fichas; diferencia absoluta ${Math.abs(c.difference)}. Estas cifras describen solo los datos inventados, no una regla general.</p>`:''}</div>${s.page<2&&s.revealed&&c.focused?button('exploration-next',s.page===0?'Cambiar la pregunta':'Cerrar con una idea fuera de pantalla'):''}${s.page===2?'<p>En papel, dibuja dos casos para estudiar una condición. Señala qué cambiarías, qué mantendrías igual y qué observarías. No hace falta realizar una prueba física.</p><p>Este taller usa registros fijos: no permite repetir ensayos ni establecer una ley física.</p>':''}`;}
 else{const before=storyVersion(s.start,s.page===0?s.ending:s.original),after=storyVersion(s.start,s.ending,true);content=`<p class="notice">Solo para el adulto · 24–35 meses. Prepara una idea breve y aparta la pantalla antes de jugar. No es una actividad digital para el pequeño.</p><p>${s.page===0?'Prepara dos momentos con un muñeco adecuado a la edad, bajo supervisión. Puedes elegir otra historia o parar.':s.page===1?'Cambia una condición: ahora el muñeco se queda guardado. Cuenta la historia solo con gestos. Puedes mantener o cambiar el final.':'Ya tienes una posibilidad. No hace falta seguirla: observa su interés y acepta sus cambios o que quiera parar.'}</p>${s.page===0?`<fieldset><legend>Un comienzo</legend><div class="controls">${Object.entries(beginnings).map(([id,label])=>`<button type="button" class="action secondary" data-story-start="${id}" aria-pressed="${s.start===id}">${label}</button>`).join('')}</div></fieldset>`:''}${s.page<2?`<fieldset><legend>${s.page===0?'Un final posible':'El final de la versión con gestos'}</legend><div class="controls">${Object.entries(endings).map(([id,label])=>`<button type="button" class="action secondary" data-story-end="${id}" aria-pressed="${s.ending===id}">${label}</button>`).join('')}</div></fieldset>`:''}<div class="exploration-pair"><article class="exploration-card"><h5>Con el muñeco</h5>${storyArt(s.page===0?s.ending:s.original)}<ol>${before.map(x=>`<li>${x}</li>`).join('')}</ol></article>${s.page>0?`<article class="exploration-card"><h5>Solo con gestos</h5>${storyArt(s.ending,true)}<ol>${after.map(x=>`<li>${x}</li>`).join('')}</ol></article>`:'<aside class="exploration-card"><h5>Deja un espacio para su idea</h5><p>Después del primer gesto, espera. Puede mirar, imitar, inventar otra cosa o no participar.</p></aside>'}</div>${s.page>0?`<p id="exploration-feedback" role="status">Mantienes el comienzo y cambias el modo de contarlo. ${s.ending===s.original?'El final elegido es el mismo.':'También has elegido otro final.'} Ninguna versión es una respuesta correcta o una tarea que el pequeño deba completar.</p>`:'<p id="exploration-feedback" role="status">La vista muestra tu propuesta, no una predicción de lo que hará el pequeño.</p>'}${s.page<2?`<div class="controls">${button('exploration-hint','Una pista para acompañar')}${button('exploration-next',s.page===0?'Ver una versión sin muñeco':'Preparar el cierre fuera de pantalla')}</div>`:'<p>Guarda la pantalla, despeja el espacio y acompaña directamente. Usa materiales adecuados, sin piezas pequeñas. Puedes hacer un solo gesto y terminar; no se registra cómo responde el pequeño.</p>'}`;}
 root.innerHTML=`<section class="exploration" aria-labelledby="exploration-title"><p class="eyebrow">${science?'9–12 años · con ayuda disponible':'Creatividad · guía del adulto'}</p><h4 id="exploration-title" tabindex="-1">${science?'Elige qué comparar':'Una historia, dos maneras'}</h4><ol class="construction-steps" aria-label="Recorrido"><li ${s.page===0?'aria-current="step"':''}>${science?'Elegir y observar':'Preparar'}</li><li ${s.page===1?'aria-current="step"':''}>Cambiar una condición</li><li ${s.page===2?'aria-current="step"':''}>Fuera de pantalla</li></ol>${content}<p id="exploration-hint-text" role="status">${s.hint?hint:''}</p><div class="controls">${s.page===2?button('exploration-finish',science?'Terminar por hoy':'Guardar la pantalla y jugar juntos'):''}${button('exploration-examples',science?'Volver a los ejemplos guiados':'Volver a la guía breve')}</div><p class="quiet">Puedes pausar o terminar arriba, sin completar el recorrido.</p></section>`;
 const on=(id,fn)=>{const el=root.querySelector('#'+id);if(el)el.onclick=fn;};
 root.querySelectorAll('[data-record]').forEach(el=>el.onchange=()=>{s[el.dataset.record]=el.value;s.revealed=false;redraw(`[data-record="${el.dataset.record}"]`);});
 root.querySelectorAll('[data-story-start]').forEach(el=>el.onclick=()=>{s.start=el.dataset.storyStart;redraw(`[data-story-start="${s.start}"]`);});
 root.querySelectorAll('[data-story-end]').forEach(el=>el.onclick=()=>{s.ending=el.dataset.storyEnd;redraw(`[data-story-end="${s.ending}"]`);});
 on('exploration-observe',()=>{s.revealed=true;redraw('#exploration-feedback');});
 on('exploration-hint',()=>{s.hint=true;root.querySelector('#exploration-hint-text').textContent=hint;});
 on('exploration-next',()=>{if(!science&&s.page===0)s.original=s.ending;s.page++;s.hint=false;if(science&&s.page===1)s.revealed=false;redraw('#exploration-title');});
 on('exploration-examples',()=>{s.open=false;examples();root.querySelector('#open-exploration')?.focus();});
 on('exploration-finish',finish);
}
